import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with the customer, date and lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'DES-HOUR', qty: 4 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 2);
});

test('createInvoice copies product details into each line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  const line = r.value.lines[0];
  assert.equal(line.sku, 'DEV-HOUR');
  assert.equal(line.name, 'Development (hour)');
  assert.equal(line.qty, 5);
  assert.equal(line.unitPrice, 9500);
  assert.equal(line.vatRate, 21);
});

test('createInvoice does not mutate input lines', () => {
  const inputLines = [{ sku: 'DEV-HOUR', qty: 3 }];
  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: inputLines,
  });
  assert.deepEqual(inputLines, [{ sku: 'DEV-HOUR', qty: 3 }]);
});

test('createInvoice reports CUSTOMER_NOT_FOUND', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports DATE_INVALID for wrong format', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026/10/07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports DATE_INVALID for fake dates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-02-30',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports NO_LINES for empty lines array', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports QTY_INVALID for non-integer qty', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 3.5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports QTY_INVALID for zero qty', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 0 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports QTY_INVALID for negative qty', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: -5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports UNKNOWN_SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'FAKE-SKU', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('lineTotal multiplies qty by unitPrice', () => {
  const line = { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 5, unitPrice: 9500, vatRate: 21 };
  assert.equal(lineTotal(line), 47500);
});

test('lineTotal handles single quantity', () => {
  const line = { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 21 };
  assert.equal(lineTotal(line), 8500);
});

test('invoiceTotals sums line totals for multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const expected = (5 * 9500) + (2 * 8500);
  assert.deepEqual(totals, { subtotal: expected, discount: 0, total: expected });
});

test('invoiceTotals with a single line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  });
  const totals = invoiceTotals(r.value);
  assert.deepEqual(totals, { subtotal: 28500, discount: 0, total: 28500 });
});

test('invoiceTotals returns zero for empty lines', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 0, discount: 0, total: 0 });
});

test('addLine adds a new line to an invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const r2 = addLine(r.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[1].sku, 'DES-HOUR');
  assert.equal(r2.value.lines[1].qty, 3);
  assert.equal(r2.value.lines[1].name, 'Design work (hour)');
});

test('addLine increases qty if SKU already exists', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const r2 = addLine(r.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].qty, 8);
});

test('addLine does not mutate original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const original = r.value;
  addLine(original, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(original.lines.length, 1);
});

test('addLine validates qty', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const r2 = addLine(r.value, { sku: 'DES-HOUR', qty: 0 });
  assert.deepEqual(r2, { ok: false, error: 'QTY_INVALID' });
});

test('addLine validates SKU exists', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const r2 = addLine(r.value, { sku: 'FAKE-SKU', qty: 1 });
  assert.deepEqual(r2, { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine refuses to modify non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 5, unitPrice: 9500, vatRate: 21 }],
  };
  const r = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine removes a line from an invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });
  const r2 = removeLine(r.value, 'DES-HOUR');
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine reports LINE_NOT_FOUND', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const r2 = removeLine(r.value, 'FAKE-SKU');
  assert.deepEqual(r2, { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine reports NO_LINES if removing the last line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const r2 = removeLine(r.value, 'DEV-HOUR');
  assert.deepEqual(r2, { ok: false, error: 'NO_LINES' });
});

test('removeLine refuses to modify non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 5, unitPrice: 9500, vatRate: 21 },
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 3, unitPrice: 8500, vatRate: 21 },
    ],
  };
  const r = removeLine(invoice, 'DES-HOUR');
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine does not mutate original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });
  const original = r.value;
  removeLine(original, 'DES-HOUR');
  assert.equal(original.lines.length, 2);
});

test('issueInvoice assigns number and changes status to issued', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r.value, []);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2026-0001');
  assert.equal(r2.value.status, 'issued');
